def isPalindrome(s):
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] == '-':
            i += 1
        elif s[j] == '-':
            j -= 1
        else:
            if s[i].lower() != s[j].lower():
                return False
            i += 1
            j -= 1
    return True
